//! The console bundle, compiled in.
//!
//! **One path.** The bundle is a table generated by `build.rs` from a hash-pinned staged tree;
//! there is no flag pointing anywhere and no directory to configure. A console directory an
//! operator could point at would be a second artifact to ship, and it would readmit version skew
//! between the console and the API in full.
//!
//! **What skew costs, stated once because it is the whole argument.** A console built against an
//! older contract does not error; it renders a figure from a field that changed meaning. Grafana's
//! "failed to load its application files" is the visible half of that class and the half we would
//! rather have. The silent half is the one that matters here, because every number this product
//! shows is a measurement somebody will act on.

use axum::http::{header, HeaderMap, StatusCode};
use axum::response::{IntoResponse, Response};

/// One embedded file.
pub struct Asset {
    /// The bundle-relative path the file is served at, no leading slash: `index.html`,
    /// `assets/...`.
    pub path: &'static str,
    /// The file's bytes, compiled in by `include_bytes!` from the staged tree.
    pub body: &'static [u8],
    /// The `Content-Type` it is served with, chosen from the extension at build time.
    pub content_type: &'static str,
    /// The file's own digest, computed at build time. Serving a `304` costs a header comparison
    /// rather than a hash of the body on every request.
    pub etag: &'static str,
}

include!(concat!(env!("OUT_DIR"), "/console_assets.rs"));

/// Is a console compiled into this binary?
#[must_use]
pub fn present() -> bool {
    !CONSOLE_ASSETS.is_empty()
}

/// Everything embedded, for the pin tests. The table itself stays private so nothing outside this
/// module can serve an asset without going through [`serve`] and its headers.
#[must_use]
pub fn assets() -> &'static [Asset] {
    CONSOLE_ASSETS
}

/// The embedded console's version and content hash, for `--version` and `/v1/stamp`.
///
/// **"Which console is in this binary" must be answerable from the artifact**, offline, the same
/// way every artifact carries the contract hash. A support conversation that
/// begins by guessing which bundle is deployed has already lost.
#[must_use]
pub fn stamp() -> Option<(&'static str, &'static str)> {
    CONSOLE_VERSION.zip(CONSOLE_HASH)
}

/// How long a content-addressed asset may be cached. One year, which is the maximum any client
/// honours and the correct answer for a name that cannot change meaning.
const IMMUTABLE: &str = "public, max-age=31536000, immutable";

/// Serve `path` from the embedded table, or `None` if this build has no such file.
///
/// **The SPA fallback is the caller's**, not this function's: an unmatched path must reach
/// `index.html` so a deep link like `/holder/i-004/0/1` renders, and that decision belongs beside
/// the route table rather than buried in a lookup.
#[must_use]
pub fn serve(path: &str, headers: &HeaderMap) -> Option<Response> {
    serve_from(CONSOLE_ASSETS, path, headers)
}

/// The rules, over whatever table they are given.
///
/// **Split from [`serve`] so the RULES can be tested without a staged bundle.** A clean checkout
/// and CI stage no console, so assertions about caching, revalidation and lookup written against
/// the global table would early-return exactly where they most need to run. None of these rules
/// depend on WHICH bundle is embedded, so none of them needs one.
fn serve_from(assets: &[Asset], path: &str, headers: &HeaderMap) -> Option<Response> {
    let wanted = path.trim_start_matches('/');
    let asset = assets.iter().find(|a| a.path == wanted)?;

    // A conditional request that already holds these bytes gets no bytes back. Without this the
    // console re-downloads its whole bundle on every load, through the operator's proxy.
    if headers
        .get(header::IF_NONE_MATCH)
        .and_then(|v| v.to_str().ok())
        .is_some_and(|presented| presented.split(',').any(|tag| tag.trim() == asset.etag))
    {
        return Some((StatusCode::NOT_MODIFIED, [(header::ETAG, asset.etag)]).into_response());
    }

    // **Vite content-hashes every name under `/assets/`, and that is what makes this safe.** A
    // file whose name encodes its contents can be cached forever, because a change produces a
    // different name rather than different bytes at the same one. `index.html` keeps a stable
    // name and therefore must be revalidated every load — it is the document that names which
    // hashed assets to fetch, so caching it is caching the whole deployment.
    let cache = if wanted.starts_with("assets/") {
        IMMUTABLE
    } else {
        "no-cache"
    };

    Some(
        (
            [
                (header::CONTENT_TYPE, asset.content_type),
                (header::CACHE_CONTROL, cache),
                (header::ETAG, asset.etag),
            ],
            asset.body,
        )
            .into_response(),
    )
}

#[cfg(test)]
mod tests {
    use super::{serve_from, Asset, CONSOLE_ASSETS};
    use axum::http::{header, HeaderMap, StatusCode};

    /// A bundle's SHAPE without a bundle: one document and one content-addressed asset, which is
    /// every case the rules distinguish.
    ///
    /// **These run everywhere — a clean checkout, a developer's machine, CI — because none of the
    /// rules under test depend on which console is embedded.**
    static FIXTURE: &[Asset] = &[
        Asset {
            path: "index.html",
            body: b"<!doctype html><title>console</title>",
            content_type: "text/html; charset=utf-8",
            etag: "\"1111111111111111\"",
        },
        Asset {
            path: "assets/index-C44seTLF.js",
            body: b"export default 0;",
            content_type: "text/javascript; charset=utf-8",
            etag: "\"2222222222222222\"",
        },
    ];

    fn cache_control(path: &str, headers: &HeaderMap) -> String {
        serve_from(FIXTURE, path, headers)
            .expect("the fixture carries this path")
            .headers()
            .get(header::CACHE_CONTROL)
            .and_then(|v| v.to_str().ok())
            .unwrap_or_default()
            .to_string()
    }

    #[test]
    fn a_hashed_asset_is_cacheable_forever_and_the_document_is_not() {
        assert_eq!(
            cache_control("/index.html", &HeaderMap::new()),
            "no-cache",
            "index.html names which hashed assets to fetch, so caching it caches the whole \
             deployment and an upgrade would serve the old console from a browser cache"
        );
        assert!(
            cache_control("/assets/index-C44seTLF.js", &HeaderMap::new()).contains("immutable"),
            "a content-addressed name cannot change meaning, so it is cacheable forever"
        );
    }

    #[test]
    fn a_client_that_already_holds_the_bytes_is_sent_none() {
        let mut headers = HeaderMap::new();
        headers.insert(
            header::IF_NONE_MATCH,
            FIXTURE[1].etag.parse().expect("etag"),
        );

        let response = serve_from(FIXTURE, "/assets/index-C44seTLF.js", &headers).expect("serves");
        assert_eq!(
            response.status(),
            StatusCode::NOT_MODIFIED,
            "a matching ETag must answer 304; without it the console re-downloads its whole \
             bundle on every load, through the operator's proxy"
        );
    }

    #[test]
    fn a_browser_offering_several_etags_is_matched_against_all_of_them() {
        // Browsers send `If-None-Match: "a", "b"` after collecting more than one cached
        // representation. Comparing the header whole would miss the match and re-send the body —
        // correct, and a silent waste of the whole bundle on every load.
        let mut headers = HeaderMap::new();
        headers.insert(
            header::IF_NONE_MATCH,
            format!("\"something-else\", {}", FIXTURE[0].etag)
                .parse()
                .expect("etag list"),
        );
        assert_eq!(
            serve_from(FIXTURE, "/index.html", &headers)
                .expect("serves")
                .status(),
            StatusCode::NOT_MODIFIED
        );
    }

    #[test]
    fn a_stale_etag_gets_the_bytes_rather_than_a_304() {
        let mut headers = HeaderMap::new();
        headers.insert(
            header::IF_NONE_MATCH,
            "\"an-older-build\"".parse().expect("etag"),
        );
        assert_eq!(
            serve_from(FIXTURE, "/index.html", &headers)
                .expect("serves")
                .status(),
            StatusCode::OK,
            "answering 304 to an ETag we do not hold would serve a client its own stale copy \
             forever"
        );
    }

    #[test]
    fn a_path_this_build_does_not_carry_is_absent_rather_than_empty() {
        // The caller turns this into the SPA fallback or the `console_not_configured` refusal.
        // Answering with empty bytes here would make a missing asset look like a served one.
        assert!(serve_from(FIXTURE, "/nothing-here.js", &HeaderMap::new()).is_none());
        assert!(serve_from(&[], "/index.html", &HeaderMap::new()).is_none());
    }

    #[test]
    fn a_leading_slash_is_optional_because_a_router_may_strip_it() {
        assert!(serve_from(FIXTURE, "index.html", &HeaderMap::new()).is_some());
        assert!(serve_from(FIXTURE, "/index.html", &HeaderMap::new()).is_some());
    }

    #[test]
    fn every_embedded_asset_declares_a_real_content_type() {
        // `build.rs` panics on an unknown extension, so this cannot fail while that holds — which
        // is the point: it states the property the build enforces, so deleting the enforcement
        // does not leave the property unasserted.
        for asset in CONSOLE_ASSETS {
            assert!(
                !asset.content_type.is_empty() && asset.content_type != "application/octet-stream",
                "{} would render as a download prompt",
                asset.path
            );
            assert!(!asset.etag.is_empty(), "{} has no ETag", asset.path);
        }
    }
}
